function AccessStatusPage({ status }: { status: "pending" | "rejected" }) {
  const { session, refresh } = useSession();
  const navigate = useNavigate();
  const logout = useMutation({
    mutationFn: () => authApi.logout(session?.csrf_token),
    onSettled: async () => {
      await refresh();
      navigate("/login", { replace: true });
    },
  });
  const pending = status === "pending";

  return (
    <main className="centered-page" id="main-content">
      <section className="status-card" aria-labelledby="access-title">
        <span className={`status-icon ${pending ? "status-icon-wait" : "status-icon-stop"}`} aria-hidden="true">
          {pending ? "…" : "!"}
        </span>
        <p className="eyebrow">Trạng thái truy cập</p>
        <h1 id="access-title">{pending ? "Tài khoản đang chờ duyệt" : "Yêu cầu truy cập đã bị từ chối"}</h1>
        <p className="muted">
          {pending
            ? "Quản trị viên cần duyệt tài khoản trước khi bạn có thể xem dữ liệu phân tích."
            : "Liên hệ quản trị viên nếu bạn cho rằng trạng thái này chưa chính xác."}
        </p>
        {session?.user?.email && <p className="identity-chip">{session.user.email}</p>}
        <button className="button button-secondary" type="button" onClick={() => logout.mutate()} disabled={logout.isPending}>
          Đăng xuất
        </button>
      </section>
    </main>
  );
}

