function AdminPage() {
  const [status, setStatus] = useState<"all" | AdminUser["status"]>("pending");
  const queryClient = useQueryClient();
  const toast = useToast();
  const users = useQuery({ queryKey: queryKeys.users, queryFn: dashboardApi.users });
  const review = useMutation({
    mutationFn: ({ id, input }: { id: string; input: UserReviewInput }) => dashboardApi.reviewUser(id, input),
    onSuccess: async (user) => {
      toast.success(`Đã cập nhật ${user.email}.`);
      await queryClient.invalidateQueries({ queryKey: queryKeys.users });
    },
  });
  const remove = useMutation({
    mutationFn: dashboardApi.deleteUser,
    onSuccess: async () => {
      toast.success("Đã xóa tài khoản.");
      await queryClient.invalidateQueries({ queryKey: queryKeys.users });
    },
  });
  const update = (user: AdminUser, input: UserReviewInput, label: string) => {
    if (window.confirm(`${label} tài khoản ${user.email}?`)) review.mutate({ id: user.id, input });
  };

  if (users.isPending) return <PageSkeleton label="Đang tải người dùng" />;
  if (users.isError) return <ResourceError error={users.error} onRetry={() => void users.refetch()} />;
  const filtered = users.data.filter((user) => status === "all" || user.status === status);

  return (
    <div className="page-stack">
      <header className="page-heading"><div><p className="eyebrow">Root administration</p><h1>Người dùng và quyền</h1><p>Duyệt tài khoản và thay đổi role. Mỗi mutation được xác nhận, bảo vệ bằng CSRF và ghi audit phía server.</p></div></header>
      {(review.isError || remove.isError) && <InlineError>{(review.error ?? remove.error)?.message}</InlineError>}
      <section className="metric-grid" aria-label="Tổng hợp người dùng"><article className="metric-card"><span className="metric-label">Tổng tài khoản</span><strong>{users.data.length}</strong></article><article className="metric-card"><span className="metric-label">Chờ duyệt</span><strong>{users.data.filter((user) => user.status === "pending").length}</strong><StatusBadge tone="warning">Cần xem xét</StatusBadge></article><article className="metric-card"><span className="metric-label">Quản trị viên</span><strong>{users.data.filter((user) => user.role === "admin" || user.role === "root").length}</strong></article></section>
      <section className="panel"><div className="panel-heading"><div><p className="eyebrow">Access review</p><h2>Danh sách tài khoản</h2></div><label className="compact-select">Trạng thái<select value={status} onChange={(event) => setStatus(event.target.value as typeof status)}><option value="pending">Chờ duyệt</option><option value="approved">Đã duyệt</option><option value="rejected">Từ chối</option><option value="all">Tất cả</option></select></label></div><div className="responsive-table" tabIndex={0} aria-label="Bảng quản trị người dùng"><table><thead><tr><th scope="col">Người dùng</th><th scope="col">Role</th><th scope="col">Trạng thái</th><th scope="col">Ngày tạo</th><th scope="col">Hành động</th></tr></thead><tbody>{filtered.map((user) => <tr key={user.id}><th scope="row"><span className="user-cell"><strong>{user.full_name || "Chưa có tên"}</strong><small>{user.email}</small></span></th><td>{user.role}</td><td><StatusBadge tone={user.status === "approved" ? "positive" : user.status === "rejected" ? "negative" : "warning"}>{statusLabel[user.status] ?? user.status}</StatusBadge></td><td>{formatDateTime(user.created_at)}</td><td><div className="table-actions">{user.role !== "root" && <><button type="button" className="text-button" onClick={() => update(user, { status: "approved", role: "user" }, "Duyệt")}>Duyệt user</button><button type="button" className="text-button" onClick={() => update(user, { status: "approved", role: "admin" }, "Cấp quyền admin cho")}>Cấp admin</button><button type="button" className="text-button danger-link" onClick={() => update(user, { status: "rejected", role: user.role === "admin" ? "admin" : "user" }, "Từ chối")}>Từ chối</button><button type="button" className="text-button danger-link" onClick={() => { if (window.confirm(`Xóa vĩnh viễn tài khoản ${user.email}? Hành động này không thể hoàn tác.`)) remove.mutate(user.id); }}>Xóa tài khoản</button></>}</div></td></tr>)}</tbody></table></div>{filtered.length === 0 && <p className="muted empty-copy">Không có tài khoản trong trạng thái này.</p>}</section>
    </div>
