function AnalysisLauncher({ initialSymbol = "FPT", onCreated }: { initialSymbol?: string; onCreated: (id: string, symbol: string) => void }) {
  const { capabilities } = useSession();
  const queryClient = useQueryClient();
  const toast = useToast();
  const watchlists = useQuery({ queryKey: queryKeys.watchlists, queryFn: dashboardApi.watchlists });
  const [runMode, setRunMode] = useState<RunMode>("single");
  const [symbol, setSymbol] = useState(initialSymbol);
  const [symbolsText, setSymbolsText] = useState("FPT\nMBB\nVHM");
  const [watchlistId, setWatchlistId] = useState("");
  const [fromDate, setFromDate] = useState(isoDate(365));
  const [toDate, setToDate] = useState(isoDate());
  const [market, setMarket] = useState("HOSE");
  const [benchmark, setBenchmark] = useState("VNIndex");
  const [provider, setProvider] = useState("");
  const [llmModel, setLlmModel] = useState("");
  const [useAi, setUseAi] = useState(true);
  const [autoRetrain, setAutoRetrain] = useState(true);
  const [stockCache, setStockCache] = useState(true);
  const [stockCacheHours, setStockCacheHours] = useState(24);
  const [newsCache, setNewsCache] = useState(true);
  const [newsCacheHours, setNewsCacheHours] = useState(24);
  const [cacheHealFull, setCacheHealFull] = useState(false);
  const [peers, setPeers] = useState("");
  const [launchMessage, setLaunchMessage] = useState("");

  const createJob = useMutation({
    mutationFn: async ({ symbols, input }: { symbols: string[]; input: Omit<JobCreateInput, "symbol"> }) => {
      const jobs = [];
      const failures: string[] = [];
      for (const item of symbols) {
        try {
          jobs.push(await dashboardApi.createJob({ ...input, symbol: item }));
        } catch (error) {
          failures.push(`${item}: ${error instanceof Error ? error.message : "không thể tạo tác vụ"}`);
        }
      }
      return { jobs, failures };
    },
    onSuccess: async ({ jobs, failures }) => {
      const firstJob = jobs[0];
      if (firstJob) {
        onCreated(firstJob.id, firstJob.symbol);
        toast.success(`Đã xếp hàng ${jobs.length} mã: ${jobs.map((job) => job.symbol).join(", ")}.`);
      }
      setLaunchMessage(failures.length > 0 ? `Không xếp hàng được ${failures.join("; ")}` : "");
      await queryClient.invalidateQueries({ queryKey: queryKeys.jobs });
      await queryClient.invalidateQueries({ queryKey: queryKeys.overview });
    },
  });

  const submit = (event: FormEvent) => {
    event.preventDefault();
    setLaunchMessage("");
    const selectedWatchlist = watchlists.data?.find((item) => item.id === watchlistId);
    const symbols = runMode === "single"
      ? parseSymbols(symbol)
      : runMode === "manual"
        ? parseSymbols(symbolsText)
        : selectedWatchlist?.symbols ?? [];
    if (symbols.length === 0) {
      setLaunchMessage("Vui lòng chọn hoặc nhập ít nhất một mã hợp lệ.");
      return;
    }
    const input: Omit<JobCreateInput, "symbol"> = {
      from_date: fromDate || null,
      to_date: toDate || null,
      benchmark,
      provider: useAi && provider ? provider : null,
      no_ai: !useAi,
      market,
      auto_retrain: useAi && autoRetrain,
      llm_model: useAi && llmModel.trim() ? llmModel.trim() : null,
      retrain_days: 0,
      retrain_periods: 5,
      retrain_threshold: 1.5,
      stock_cache: stockCache,
      stock_cache_hours: stockCacheHours,
      news_cache: newsCache,
      news_cache_hours: newsCacheHours,
      cache_heal_full: cacheHealFull,
      peers: peers.trim() || null,
    };
    createJob.mutate({ symbols, input });
  };

  return (
    <form className="launcher-form" onSubmit={submit}>
      {createJob.isError && <InlineError>{createJob.error.message}</InlineError>}
      {launchMessage && <InlineError>{launchMessage}</InlineError>}
      <div className="form-grid">
        <label className="field">Chế độ chạy<select value={runMode} onChange={(event) => setRunMode(event.target.value as RunMode)}><option value="single">Một mã</option><option value="manual">Nhập danh sách</option><option value="watchlist">Watchlist</option></select></label>
        {runMode === "single" && <label className="field">Mã chứng khoán<input value={symbol} onChange={(event) => setSymbol(event.target.value.toUpperCase())} required pattern="[A-Za-z0-9]{1,10}" maxLength={10} /></label>}
        {runMode === "manual" && <label className="field field-wide">Danh sách mã<textarea value={symbolsText} onChange={(event) => setSymbolsText(event.target.value.toUpperCase())} rows={3} placeholder="FPT, MBB, VHM" /></label>}
        {runMode === "watchlist" && <label className="field">Watchlist<select value={watchlistId} onChange={(event) => setWatchlistId(event.target.value)} required><option value="">Chọn watchlist</option>{watchlists.data?.filter((item) => item.enabled).map((item) => <option key={item.id} value={item.id}>{item.name} · {item.symbols.length} mã</option>)}</select></label>}
        <label className="field">Từ ngày<input type="date" value={fromDate} max={toDate} onChange={(event) => setFromDate(event.target.value)} /></label>
        <label className="field">Đến ngày<input type="date" value={toDate} min={fromDate} max={isoDate()} onChange={(event) => setToDate(event.target.value)} /></label>
        <label className="field">Sàn<select value={market} onChange={(event) => setMarket(event.target.value)}><option>HOSE</option><option>HNX</option><option>UPCOM</option></select></label>
        <label className="field">Benchmark<select value={benchmark} onChange={(event) => setBenchmark(event.target.value)}><option>VNIndex</option><option>VN30</option><option>HNXIndex</option></select></label>
        <label className="field">Nhà cung cấp AI<select value={provider} onChange={(event) => setProvider(event.target.value)} disabled={!useAi}><option value="">Theo cấu hình backend</option>{capabilities?.providers.map((item) => <option key={item} value={item}>{item}</option>)}</select></label>
        <label className="check-field"><input type="checkbox" checked={useAi} onChange={(event) => setUseAi(event.target.checked)} />Phân tích với AI</label>
      </div>
      <details className="launcher-advanced">
        <summary>Tùy chọn AI, model và cache</summary>
        <div className="form-grid advanced-grid">
          <label className="field">LLM model<input value={llmModel} onChange={(event) => setLlmModel(event.target.value)} disabled={!useAi} maxLength={100} placeholder="Theo provider config" /></label>
          <label className="field">Mã cùng ngành<input value={peers} onChange={(event) => setPeers(event.target.value.toUpperCase())} maxLength={200} placeholder="VNM, MSN, SAB" /></label>
          <label className="check-field"><input type="checkbox" checked={autoRetrain} onChange={(event) => setAutoRetrain(event.target.checked)} disabled={!useAi} />Tự retrain AI-2/ML</label>
          <label className="check-field"><input type="checkbox" checked={stockCache} onChange={(event) => setStockCache(event.target.checked)} />Cache dữ liệu SSI</label>
          <label className="field">Cache SSI (giờ)<input type="number" min="0.5" max="720" step="0.5" value={stockCacheHours} onChange={(event) => setStockCacheHours(Number(event.target.value))} disabled={!stockCache} /></label>
          <label className="check-field"><input type="checkbox" checked={newsCache} onChange={(event) => setNewsCache(event.target.checked)} disabled={!useAi} />Cache tin tức AI</label>
          <label className="field">Cache tin (giờ)<input type="number" min="0.5" max="720" step="0.5" value={newsCacheHours} onChange={(event) => setNewsCacheHours(Number(event.target.value))} disabled={!useAi || !newsCache} /></label>
          <label className="check-field"><input type="checkbox" checked={cacheHealFull} onChange={(event) => setCacheHealFull(event.target.checked)} disabled={!stockCache} />Cào lại toàn bộ dữ liệu</label>
        </div>
      </details>
      <div className="button-row"><button className="button button-primary" type="submit" disabled={createJob.isPending}>{createJob.isPending ? "Đang gửi…" : "Chạy phân tích"}</button><span className="muted small-copy">Dữ liệu EOD, không phải báo giá realtime.</span></div>
    </form>
  );
}

